// src/post_llm_validator.js
// CETIP - Phase 3: Post-LLM Guard-Rail Validator
// Receives the LLM JSON response, parses decisions, and applies a deterministic fallback.
// The LLM provides semantic understanding; this code enforces structural safety.

console.log("[PostLLMValidator] Starting guard-rail validation...");

const inputData = items[0].json;

// --- 1. Parse LLM Response ---
let llm_decisions = [];

try {
    // The LLM HTTP response body is in items[0].json (n8n HTTP Request node output)
    // We expect an array of objects matching rows_parsed
    const llmBody = inputData.body || inputData;

    // Try to extract JSON from the LLM's response (it may wrap it in markdown ```json blocks)
    let rawText = "";
    if (llmBody.choices && llmBody.choices[0]) {
        rawText = llmBody.choices[0].message.content;
    } else if (typeof llmBody === "string") {
        rawText = llmBody;
    } else if (llmBody.outputs) {
        rawText = llmBody.outputs[0].text || "";
    }

    // Strip markdown code fences if present
    const jsonMatch = rawText.match(/```(?:json)?\s*([\s\S]*?)```/) || [null, rawText];
    const parsed = JSON.parse(jsonMatch[1].trim()); llm_decisions = parsed.decisions || parsed;
    console.log(`[PostLLMValidator] LLM returned ${llm_decisions.length} decisions.`);
} catch (e) {
    console.log(`[PostLLMValidator] WARNING: Failed to parse LLM response (${e.message}). Falling back to deterministic validation.`);
    llm_decisions = [];
}

// --- 2. Deterministic Fallback Regex (safety net if LLM fails/hallucinates) ---
const REGEX = {
    montant: /^\d{1,6},\d{2}$/,
    date_vir: /^\d{8}$/,
    date_soin: /^\d{8}$/,
    email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
    num_ps: /^\d+$/,
    numvir: /^\d+$/,
    nb_actes: /^\d+$/
};
const VALID_CODE_ACTE = ['C', 'CS', 'V', 'AIS', 'AMK', 'AMI', 'BSB'];

// Retrieve the original rows from the pre-parser 
let rows_parsed = [];
try {
    // CORRECTION ICI : Utilisation de .first() pour s'assurer que n8n trouve bien les données
    rows_parsed = $('Pre-Parser').first().json.rows_parsed || [];
} catch(e) {
    console.log("[PostLLMValidator] Could not access Pre-Parser data via $() shorthand. Using fallback.");
    rows_parsed = inputData.rows_parsed || [];
}

const meta = {
    email_emetteur: inputData.email_emetteur || "unknown@cetip.fr",
    date_fichier: inputData.date_fichier || "INCONNU",
    fichier_source: inputData.fichier_source || "unknown",
    db_ids: inputData.db_ids || []
};

// --- 3. Apply decisions row by row ---
const rows_valides = [];
const rows_rejetees = [];
const psRejetMap = {};

for (let i = 0; i < rows_parsed.length; i++) {
    const row = rows_parsed[i];
    const ps = row.num_ps;
    const llm = llm_decisions[i] || {};

    // Contagion: if PS already rejected, reject all its lines
    if (psRejetMap[ps]) {
        row.raison_rejet = psRejetMap[ps];
        row.llm_decision = "CONTAGION";
        rows_rejetees.push(row);
        continue;
    }

    let raison = null;
    let anomalie_semantique = llm.anomalie_semantique || null;

    // A. If LLM says invalid, trust it
    if (llm.is_valid === false) {
        raison = llm.raison_rejet || "REJET_LLM";
    }

    // B. Deterministic fallback (always run as safety net)
    if (!raison) {
        const required = ['num_ps','email','bic','iban','intitule','montant','date_vir','numvir','code_acte','specialite','region','date_soin','nb_actes'];
        for (const f of required) {
            if (!row[f] || row[f].trim() === "") { raison = `CHAMP_MANQUANT_${f.toUpperCase()}`; break; }
        }
    }
    if (!raison && !REGEX.montant.test(row.montant)) raison = "FORMAT_MONTANT";
    if (!raison && !REGEX.email.test(row.email)) raison = "FORMAT_EMAIL";
    if (!raison && !REGEX.num_ps.test(row.num_ps)) raison = "FORMAT_NUM_PS";
    if (!raison && !REGEX.date_vir.test(row.date_vir)) raison = "FORMAT_DATE_VIR";
    if (!raison && !REGEX.date_soin.test(row.date_soin)) raison = "FORMAT_DATE_SOIN";
    if (!raison && !VALID_CODE_ACTE.includes(row.code_acte)) raison = "CODE_ACTE_INVALIDE";

    if (raison) {
        psRejetMap[ps] = raison;
        row.raison_rejet = raison;
        row.llm_decision = llm.is_valid === false ? "LLM_REJECT" : "REGEX_REJECT";
        rows_rejetees.push(row);
    } else {
        // Valid row — attach LLM enrichments
        row.anomalie_semantique = anomalie_semantique;
        row.correction_suggeree = llm.correction_suggeree || null;
        row.llm_decision = "VALID";
        rows_valides.push(row);
    }
}

const ps_valides = [...new Set(rows_valides.map(r => r.num_ps))];
const ps_rejetes = Object.keys(psRejetMap);

console.log(`[PostLLMValidator] Validation complete:`);
console.log(`  - ${rows_valides.length} valid rows (${ps_valides.length} PS)`);
console.log(`  - ${rows_rejetees.length} rejected rows (${ps_rejetes.length} PS)`);
console.log(`  - ${rows_valides.filter(r => r.anomalie_semantique).length} semantic anomalies flagged by LLM`);

return [{
    json: {
        rows_valides,
        rows_rejetees,
        ps_valides,
        ps_rejetes,
        nb_lignes_valides: rows_valides.length,
        nb_lignes_rejetees: rows_rejetees.length,
        has_rejets: rows_rejetees.length > 0,
        ...meta
    }
}];

// src/rejet_builder.js
// n8n Code Node for building the CSV of rejected rows

console.log("Starting rejet_builder node...");

if (!items || !items.length || !items[0].json) {
    console.log("Error: No input data provided");
    return [{ json: { error: "No input data" } }];
}

// Read rows_rejetees from input
const rows_rejetees = items[0].json.rows_rejetees || [];

// The 13 Enriched Columns + RAISON_REJET
const headers = [
    "NUM_PS", "EMAIL", "BIC", "IBAN", "INTITULE", "MONTANT", "DATE_VIR",
    "NUMVIR", "CODE_ACTE", "SPECIALITE", "REGION", "DATE_SOIN",
    "NB_ACTES", "RAISON_REJET"
];

// Helper to escape fields for proper CSV format
function escapeCSV(field) {
    if (field === null || field === undefined) return "";
    const str = String(field);
    // If field contains comma, quote, or newline, wrap in quotes and escape quotes
    if (str.includes(",") || str.includes("\"") || str.includes("\n")) {
        return `"${str.replace(/"/g, '""')}"`;
    }
    return str;
}

const csvLines = [];

// 1. Add header
csvLines.push(headers.join(","));

// 2. Add data rows
for (const row of rows_rejetees) {
    const line = [
        escapeCSV(row.num_ps),
        escapeCSV(row.email),
        escapeCSV(row.bic),
        escapeCSV(row.iban),
        escapeCSV(row.intitule),
        escapeCSV(row.montant),
        escapeCSV(row.date_vir),
        escapeCSV(row.numvir),
        escapeCSV(row.code_acte),
        escapeCSV(row.specialite),
        escapeCSV(row.region),
        escapeCSV(row.date_soin),
        escapeCSV(row.nb_actes),
        escapeCSV(row.raison_rejet) // The reason from validators.js
    ];
    csvLines.push(line.join(","));
}

// 3. Add summary row at the end
csvLines.push(`TOTAL_REJETS,${rows_rejetees.length}`);

// Combine into single text body
const csv_content = csvLines.join("\n");

console.log(`Generated CSV with ${rows_rejetees.length} rejected rows.`);

return [{
    json: {
        csv_content: csv_content,
        nb_rejets: rows_rejetees.length
    }
}];

// src/grouper.js
// n8n Code Node for grouping valid Bordereau rows by Professionnel de Santé (PS)

console.log("Starting grouper node...");

if (!items || !items.length || !items[0].json || !items[0].json.rows_valides) {
    console.log("Error: No valid rows provided from validators");
    return [{ json: { error: "No valid rows" } }];
}

const rowsValides = items[0].json.rows_valides;
const psGroups = {};

console.log(`Processing ${rowsValides.length} valid rows for grouping.`);

for (let i = 0; i < rowsValides.length; i++) {
    const row = rowsValides[i];
    const ps = row.num_ps;

    // Initialize group if it doesn't exist
    if (!psGroups[ps]) {
        psGroups[ps] = {
            num_ps: ps,
            email: row.email,
            intitule: row.intitule,
            specialite: row.specialite,
            region: row.region,
            bic: row.bic,
            iban: row.iban,
            lignes: [],
            montant_total: 0,
            nb_actes_total: 0,
            codes_actes_set: new Set()
        };
    }

    // Add row to group's lines — with derived montant_par_acte per line (Issue 8: ML needs per-line value)
    const montantParsed = parseFloat(row.montant.replace(',', '.'));
    const nbActesParsed = parseInt(row.nb_actes, 10);
    const montantParActe = nbActesParsed > 0 ? Math.round((montantParsed / nbActesParsed) * 100) / 100 : montantParsed;

    row.montant_par_acte = montantParActe;
    psGroups[ps].lignes.push(row);

    // Accumulate group totals
    psGroups[ps].montant_total += montantParsed;
    psGroups[ps].nb_actes_total += nbActesParsed;

    // Track unique code_acte
    if (row.code_acte) {
        psGroups[ps].codes_actes_set.add(row.code_acte);
    }
}

const resultItems = [];

for (const ps in psGroups) {
    const group = psGroups[ps];

    // Fix JS floating point precision issues (e.g. 25324.180000000004 -> 25324.18)
    const montantTotalRounded = Math.round(group.montant_total * 100) / 100;

    // Calculate average amount per act
    let montantMoyenParActe = 0;
    if (group.nb_actes_total > 0) {
        montantMoyenParActe = Math.round((montantTotalRounded / group.nb_actes_total) * 100) / 100;
    }

    resultItems.push({
        json: {
            num_ps: group.num_ps,
            email: group.email,
            intitule: group.intitule,
            specialite: group.specialite,
            region: group.region,
            bic: group.bic,
            iban: group.iban,
            montant_total: montantTotalRounded,
            nb_actes_total: group.nb_actes_total,
            montant_moyen_par_acte: montantMoyenParActe,
            nb_lignes: group.lignes.length,
            codes_actes_uniques: Array.from(group.codes_actes_set),
            lignes: group.lignes
        }
    });
}

console.log(`Grouped into ${resultItems.length} unique PS items.`);

// Return one item per PS. This feeds directly into n8n's Split In Batches node perfectly.
return resultItems;

// Inject ML results and HTML template
var ps = $('SplitInBatches').first().json;
var ml = items[0].json;

ps.flag_anomalie = ml.flag_anomalie;
ps.score_anomalie = ml.score_anomalie;
