INSERT INTO bronze_bordereaux (
    num_ps, email, intitule, specialite, region, bic, iban, 
    montant, nb_actes, code_acte, date_vir, date_soin, numvir, 
    flag_anomalie, score_anomalie, fichier_source, date_ingestion
) 
VALUES 
{{ $('Template Filler').item.json.lignes.map(l => `('${$('Template Filler').item.json.num_ps}', '${$('Template Filler').item.json.email}', '${$('Template Filler').item.json.intitule.replace(/'/g, "''")}', '${$('Template Filler').item.json.specialite}', '${$('Template Filler').item.json.region}', '${$('Template Filler').item.json.bic}', '${$('Template Filler').item.json.iban}', ${parseFloat(l.montant.replace(',','.'))}, ${l.nb_actes}, '${l.code_acte}', '${l.date_vir}', '${l.date_soin}', '${l.numvir}', '${$('Template Filler').item.json.flag_anomalie}', ${$('Template Filler').item.json.score_anomalie}, '${$('Pre-Parser').first().json.fichier_source}', NOW())`).join(',') }}
ON CONFLICT DO NOTHING;
